import{describe,it,expect}from"vitest";import{AWARD_ENCYCLOPEDIA,getAwardDetailsByKey,searchAwardsAndRecipients,filterAwardsByCategory}from"../../frontend/js-modules/national-awards.js";describe("Pradhan Mantri Rashtriya Bal Puraskar Explorer Dataset",()=>{it("contains the 'pradhan-mantri-rashtriya-bal-puraskar' dataset entry",()=>{const a=AWARD_ENCYCLOPEDIA["pradhan-mantri-rashtriya-bal-puraskar"];expect(a).toBeDefined(),expect(a.id).toBe("pradhan-mantri-rashtriya-bal-puraskar"),expect(a.name).toContain("Pradhan Mantri Rashtriya Bal Puraskar"),expect(a.category).toBe("children"),expect(a.establishedYear).toBe("1996")}),it("contains all required dataset sections (Eligibility, History, Medal Design, Winners, Facts)",()=>{const a=getAwardDetailsByKey("pradhan-mantri-rashtriya-bal-puraskar");expect(a).not.toBeNull(),expect(a.eligibility).toBeTruthy(),expect(a.history).toBeTruthy(),expect(a.medalDesign).toBeTruthy(),expect(Array.isArray(a.notableWinners)).toBe(!0),expect(a.notableWinners.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(a.interestingFacts)).toBe(!0),expect(a.interestingFacts.length).toBeGreaterThanOrEqual(3)}),it("includes notable child achievers in dataset",()=>{const a=getAwardDetailsByKey("pradhan-mantri-rashtriya-bal-puraskar").notableWinners.map(a=>a.name);expect(a.some(a=>a.includes("Prasiddhi Singh"))).toBe(!0),expect(a.some(a=>a.includes("Gitanjali Rao"))).toBe(!0),expect(a.some(a=>a.includes("Vyom Ahuja"))).toBe(!0),expect(a.some(a=>a.includes("Anand Krishna Mishra"))).toBe(!0)}),it("searches and filters Pradhan Mantri Rashtriya Bal Puraskar accurately",()=>{const a=searchAwardsAndRecipients("Pradhan Mantri Rashtriya Bal Puraskar");expect(a.length).toBeGreaterThanOrEqual(1),expect(a.some(a=>"pradhan-mantri-rashtriya-bal-puraskar"===a.id)).toBe(!0);const e=searchAwardsAndRecipients("Gitanjali Rao");expect(e.length).toBeGreaterThanOrEqual(1),expect(e[0].id).toBe("pradhan-mantri-rashtriya-bal-puraskar");const t=filterAwardsByCategory("children");expect(t.some(a=>"pradhan-mantri-rashtriya-bal-puraskar"===a.id)).toBe(!0)})});